#define sz(a) int((a).size())

int main() {
#ifdef _DEBUG
	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);
#endif

	int n, k;
	string t;
	cin >> n >> k >> t;

	vector<int> p(n);
	for (int i = 1; i < sz(t); ++i) {
		int j = p[i - 1];
		while (j > 0 && t[j] != t[i])
			j = p[j - 1];
		if (t[i] == t[j])
			++j;
		p[i] = j;
	}

	int len = sz(t) - p[n - 1];

	for (int i = 0; i < k - 1; ++i)
		cout << t.substr(0, len);
	cout << t << endl;

	return 0;
}

